    if isinstance(data,list):
        items=data
    elif isinstance(data,dict) and 'data' in data and 'alerts' in data['data']:
        items=data['data']['alerts']
    else:
        continue
    for a in items:
        if a.get('state')!='firing':
            continue
        lbl=a.get('labels',{})
        if lbl.get('namespace')!='otel-demo':
            continue
        alerts.append({
            'alertname': lbl.get('alertname'),
            'service': lbl.get('service_name'),
            'severity': lbl.get('severity'),
            'activeAt': a.get('activeAt')
        })
# aggregate
summary={}
for a in alerts:
    key=(a['alertname'], a.get('service'))
    if key not in summary:
        summary[key]={'count':1,'first':a['activeAt'],'last':a['activeAt'],'severity':a['severity']}
